/// A data structure that can be deserialized from any data format supported
/// by Serde.
///
/// Serde provides `Deserialize` implementations for many Rust primitive and
/// standard library types. The only other thing you might need is a format
/// that can deserialize from your data source.
///
/// # Implementing Deserialize
///
/// Types that own their data can implement `Deserialize` by hand or via
/// `#[derive(Deserialize)]`.
pub trait Deserialize<'de>: Sized {
    /// Deserialize this value from the given Serde deserializer.
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: Deserializer<'de>;

    /// Deserializes a value into `self` from the given Deserializer.
    ///
    /// The default implementation just calls [`Deserialize::deserialize`] and
    /// then assigns to `self`.
    #[inline]
    fn deserialize_in_place<D>(
        deserializer: D,
        place: &mut Self,
    ) -> Result<(), D::Error>
    where
        D: Deserializer<'de>,
    {
        *place = Deserialize::deserialize(deserializer)?;
        Ok(())
    }
}
